// SPDX-License-Identifier: MIT
// Stonecourse (Prismheart campaign), plain C++17 for the Unreal binding. A port of tools/minigames/stonecourse.py
// (unreal-team), which stays the rules authority. Seeding is CPython-compatible (DaedalusPyRandomCore.h,
// "stonecourse:<seed>:<difficulty>") and the only draws are randrange at setup (repeated until the mason's bounded
// search can finish the wall); nothing is random after. Byte parity goes through
// engines/unreal/core-test/stonecourse_parity.txt (stonecourse_core_test.cpp), generated by
// tools/minigames/stonecourse_parity.py.
//
// Rules: a wall Width cells across and Courses high. Stones (widths 1..3) come off the supply in order; the next
// stone is set at a column and lands on the lowest course whose cells there are empty, which must be fully supported
// by the course below (or the footing). A course with no gaps locks (+CourseScore). A stone may be skipped to the
// rubble Skips times. Every course locked finishes the wall (+StoneBonus per stone left, +SkipBonus per skip left);
// the supply running out, or a stone that fits nowhere with no skips left, fails the build. The mason (demo) is a
// bounded exact search (columns left to right, then skip; SearchNodes budget) with a gap-aware greedy fallback.
#pragma once
#include "DaedalusPyRandomCore.h"
#include <algorithm>
#include <array>
#include <cstdint>
#include <string>
#include <unordered_map>
#include <vector>

namespace daedalus { namespace stonecourse {

inline const char* GameId() { return "stonecourse"; }
inline const char* Title() { return "Stonecourse"; }

constexpr int MinWidth = 1, MaxWidth = 3;
constexpr int CourseScore = 10, StoneBonus = 2, SkipBonus = 3;
constexpr int SearchNodes = 20000, MaxRedraws = 50;
constexpr int MaxWallWidth = 12, MaxCourses = 8;

struct Difficulty { const char* Name; int Width; int Courses; int Supply; int Skips; };
inline const Difficulty* Difficulties()
{
	static const Difficulty Table[] = { { "easy", 7, 4, 20, 3 }, { "normal", 8, 5, 26, 3 }, { "hard", 9, 6, 34, 3 } };
	return Table;
}
constexpr int DifficultyCount = 3;
inline const Difficulty* FindDifficulty(const std::string& Name)
{
	for (int I = 0; I < DifficultyCount; ++I) if (Name == Difficulties()[I].Name) return &Difficulties()[I];
	return nullptr;
}

/** An action: a column, or Skip. */
constexpr int Skip = -1;

/** The wall as one byte per cell, course-major from the footing: '0' empty, '1' stone. */
using Wall = std::string;

struct Game
{
	const Difficulty* Diff = nullptr;
	std::vector<int> Stones;
	Wall Cells;
	int Index = 0, Locked = 0, SkipsLeft = 0;
	int Score = 0; bool Over = false, Won = false;
	pyrandom::PyRandom Rng;

	enum class Act { Ok, NoSkips, SupplyEmpty, NoRest, GameOver };

	int Width() const noexcept { return Diff ? Diff->Width : 0; }
	int Courses() const noexcept { return Diff ? Diff->Courses : 0; }
	int Supply() const noexcept { return static_cast<int>(Stones.size()); }
	int NextStone() const noexcept { return Index < Supply() ? Stones[static_cast<size_t>(Index)] : 0; }
	bool Filled(int Course, int Col) const noexcept { return Cells[static_cast<size_t>(Course * Width() + Col)] == '1'; }
	bool CourseFull(int Course) const noexcept { for (int C = 0; C < Width(); ++C) if (!Filled(Course, C)) return false; return true; }
	/** Game.fresh: nothing set yet, so the screen shows its tutorial rows. */
	bool FreshWall() const noexcept { return Index == 0 && !Over; }

	/** Game.landing on an arbitrary wall: the course a `Size` stone at `Col` lands on, or -1. */
	static int LandOn(const Wall& W, int Width, int Courses, int Col, int Size) noexcept
	{
		if (Size <= 0 || Col < 0 || Col + Size > Width) return -1;
		for (int K = 0; K < Courses; ++K)
		{
			bool Empty = true;
			for (int C = Col; C < Col + Size; ++C) if (W[static_cast<size_t>(K * Width + C)] == '1') { Empty = false; break; }
			if (!Empty) continue;
			if (K == 0) return 0;
			for (int C = Col; C < Col + Size; ++C) if (W[static_cast<size_t>((K - 1) * Width + C)] != '1') return -1;
			return K;
		}
		return -1;
	}
	int Landing(int Col, int Size = 0) const noexcept { return LandOn(Cells, Width(), Courses(), Col, Size ? Size : NextStone()); }
	/** Game.placements: legal columns for the next stone, left to right. */
	int Placements(std::array<int, MaxWallWidth>& Out) const noexcept
	{
		int N = 0;
		for (int C = 0; C < Width(); ++C) if (Landing(C) >= 0) Out[static_cast<size_t>(N++)] = C;
		return N;
	}

	/** PrismGame.start + Game.setup: draw supplies until the bounded search finishes the wall. False on an unknown difficulty. */
	bool Start(std::uint32_t Seed, const std::string& DifficultyName)
	{
		Diff = FindDifficulty(DifficultyName);
		if (!Diff || Diff->Width > MaxWallWidth || Diff->Courses > MaxCourses) return false;
		Rng.Seed(std::string(GameId()) + ":" + std::to_string(Seed) + ":" + DifficultyName);
		Score = 0; Over = Won = false;
		for (int Attempt = 0; Attempt < MaxRedraws; ++Attempt)
		{
			Stones.assign(static_cast<size_t>(Diff->Supply), 0);
			for (int& S : Stones) S = MinWidth + static_cast<int>(Rng.RandRange(static_cast<std::uint32_t>(MaxWidth - MinWidth + 1)));
			Cells.assign(static_cast<size_t>(Diff->Width * Diff->Courses), '0');
			Index = Locked = 0; SkipsLeft = Diff->Skips;
			int First = 0;
			if (Search(First)) break;
		}
		return true;
	}

	/** Game.act: `Action` is a column or Skip. `Result` mirrors the Python result text. */
	Act Step(int Action, std::string& Result)
	{
		if (Over) return Act::GameOver;
		if (Action == Skip)
		{
			if (SkipsLeft <= 0) return Act::NoSkips;
			if (Index >= Supply()) return Act::SupplyEmpty;
			--SkipsLeft; ++Index;
			Result = Settle("skip: stone to the rubble, " + std::to_string(SkipsLeft) + " skips left");
			return Act::Ok;
		}
		const int K = Landing(Action);
		if (K < 0) return Act::NoRest;
		const int Size = NextStone();
		for (int C = Action; C < Action + Size; ++C) Cells[static_cast<size_t>(K * Width() + C)] = '1';
		++Index;
		const int Newly = CourseFull(K) ? 1 : 0;
		Locked += Newly;
		Score += CourseScore * Newly;
		Result = Settle(std::to_string(Action) + ": " + std::to_string(Size) + "-stone on course " + std::to_string(K) + (Newly ? "; the course locks" : ""));
		return Act::Ok;
	}

	std::string Settle(const std::string& Text)
	{
		if (Locked == Courses())
		{
			Score += StoneBonus * (Supply() - Index) + SkipBonus * SkipsLeft;
			Over = Won = true;
			return Text + "; the wall stands";
		}
		if (Index >= Supply()) { Over = true; Won = false; return Text + "; the supply runs out"; }
		std::array<int, MaxWallWidth> Cols{};
		if (Placements(Cols) == 0 && SkipsLeft <= 0) { Over = true; Won = false; return Text + "; the stone fits nowhere"; }
		return Text;
	}

	/** Game.preview: (legal, course, locks) for setting the next stone, without setting it. */
	bool Preview(int Action, int& Course, bool& Locks) const noexcept
	{
		Course = -1; Locks = false;
		if (Over) return false;
		if (Action == Skip) return SkipsLeft > 0 && Index < Supply();
		Course = Landing(Action);
		if (Course < 0) return false;
		const int Size = NextStone();
		Locks = true;
		for (int C = 0; C < Width(); ++C) if (!Filled(Course, C) && (C < Action || C >= Action + Size)) { Locks = false; break; }
		return true;
	}

	/** Game.demo_action, the mason: the bounded search's first action, else the greedy pick. */
	int DemoAction() const
	{
		int Found = 0;
		if (Search(Found)) return Found;
		return GreedyPick();
	}

	/** Game.greedy_pick: lowest course, no gap narrower than the smallest stone still coming, leftmost; skip when every placement leaves one. */
	int GreedyPick() const noexcept
	{
		std::array<int, MaxWallWidth> Cols{};
		const int N = Placements(Cols);
		if (N == 0) return SkipsLeft > 0 ? Skip : 0;
		int Smallest = MaxWidth + 1;
		for (int I = Index + 1; I < Supply(); ++I) Smallest = std::min(Smallest, Stones[static_cast<size_t>(I)]);
		if (Smallest > MaxWidth) Smallest = MinWidth;
		int BestCol = Cols[0], BestKey[3] = { 0, 0, 0 }; bool Have = false;
		for (int I = 0; I < N; ++I)
		{
			const int Col = Cols[static_cast<size_t>(I)], K = Landing(Col), Size = NextStone();
			int Bad = 0, Run = 0;
			for (int C = 0; C <= Width(); ++C)
			{
				const bool EmptyCell = C < Width() && !Filled(K, C) && (C < Col || C >= Col + Size);
				if (EmptyCell) ++Run;
				else { if (Run && Run < Smallest) ++Bad; Run = 0; }
			}
			const int Key[3] = { Bad, K, Col };
			if (!Have || std::lexicographical_compare(Key, Key + 3, BestKey, BestKey + 3)) { Have = true; BestCol = Col; std::copy(Key, Key + 3, BestKey); }
		}
		if (BestKey[0] > 0 && SkipsLeft > 0) return Skip;
		return BestCol;
	}

	/** Game.search: the first action of a line that locks every course within the supply and skips. */
	bool Search(int& First) const
	{
		std::unordered_map<std::string, bool> Memo;
		int Nodes = 0;
		if (Index >= Supply()) return false;
		const int Size = NextStone();
		for (int Col = 0; Col < Width(); ++Col)
		{
			const int K = LandOn(Cells, Width(), Courses(), Col, Size);
			if (K < 0) continue;
			Wall Next = Cells;
			for (int C = Col; C < Col + Size; ++C) Next[static_cast<size_t>(K * Width() + C)] = '1';
			const int Sub = Recurse(Next, Index + 1, SkipsLeft, Memo, Nodes);
			if (Sub == 1) { First = Col; return true; }
			if (Nodes > SearchNodes) return false;
		}
		if (SkipsLeft > 0 && Recurse(Cells, Index + 1, SkipsLeft - 1, Memo, Nodes) == 1) { First = Skip; return true; }
		return false;
	}
	/** 1 = a finishing line exists, 0 = none, -1 = the budget ran out (same bookkeeping as the Python rec). */
	int Recurse(const Wall& W, int At, int Skips, std::unordered_map<std::string, bool>& Memo, int& Nodes) const
	{
		std::string Key = W; Key.push_back(static_cast<char>(At)); Key.push_back(static_cast<char>(Skips));
		const auto Found = Memo.find(Key);
		if (Found != Memo.end()) return Found->second ? 1 : 0;
		++Nodes;
		if (Nodes > SearchNodes) return -1;
		int Empty = 0;
		for (char Ch : W) if (Ch == '0') ++Empty;
		if (Empty == 0) { Memo[Key] = true; return 1; }
		int Left = 0;
		for (int I = At; I < Supply(); ++I) Left += Stones[static_cast<size_t>(I)];
		if (At >= Supply() || Left < Empty) { Memo[Key] = false; return 0; }
		const int Size = Stones[static_cast<size_t>(At)];
		for (int Col = 0; Col < Width(); ++Col)
		{
			const int K = LandOn(W, Width(), Courses(), Col, Size);
			if (K < 0) continue;
			Wall Next = W;
			for (int C = Col; C < Col + Size; ++C) Next[static_cast<size_t>(K * Width() + C)] = '1';
			const int Sub = Recurse(Next, At + 1, Skips, Memo, Nodes);
			if (Sub == 1) { Memo[Key] = true; return 1; }
			if (Nodes > SearchNodes) return -1;
		}
		if (Skips > 0)
		{
			const int Sub = Recurse(W, At + 1, Skips - 1, Memo, Nodes);
			if (Sub == 1) { Memo[Key] = true; return 1; }
			if (Nodes > SearchNodes) return -1;
		}
		Memo[Key] = false;
		return 0;
	}

	/** Parity text: course rows from the footing, ';'-joined, '0'/'1' per cell. */
	std::string WallString() const
	{
		std::string Out;
		for (int K = 0; K < Courses(); ++K)
		{
			if (K) Out.push_back(';');
			Out.append(Cells, static_cast<size_t>(K * Width()), static_cast<size_t>(Width()));
		}
		return Out;
	}
	std::string StonesString() const
	{
		std::string Out;
		for (size_t I = 0; I < Stones.size(); ++I) { if (I) Out.push_back(','); Out += std::to_string(Stones[I]); }
		return Out.empty() ? "-" : Out;
	}
};

inline std::string ActionText(int Action) { return Action == Skip ? "skip" : std::to_string(Action); }
inline bool ActionFromText(const std::string& Text, int& Out)
{
	if (Text == "skip") { Out = Skip; return true; }
	if (Text.empty()) return false;
	for (char Ch : Text) if (Ch < '0' || Ch > '9') return false;
	Out = std::stoi(Text);
	return true;
}

} } // namespace daedalus::stonecourse
